={{ (() => {
  // Valida el payload enviado por la Neon Function bulletinai antes de invocar al modelo IA
  const body = $('Webhook (Cartelera IA S.I.G.A.)').item.json.body || {};
  const errors = [];
  const ALLOWED_MODES = ['chat', 'draft', 'improve', 'summarize'];
  const REQUIRED_SCHEMA = {
    type: 'object',
    properties: {
      source: { type: 'string', enum: ['siga_bulletin_studio'], description: 'Origen autorizado de S.I.G.A.' },
      message: { type: 'string', minLength: 2, maxLength: 1200, description: 'Instrucción del editor' },
      mode: { type: 'string', enum: ALLOWED_MODES, description: 'Modo de asistencia editorial' },
      draft: { type: 'object', description: 'Borrador actual de la carta' },
      history: { type: 'array', maxItems: 6, description: 'Historial reciente desidentificado' }
    },
    required: ['source', 'message']
  };

  if (body.source !== 'siga_bulletin_studio') {
    errors.push({ p: 'source', m: 'Valor "source" inválido o ausente', d: 'Debe ser siga_bulletin_studio' });
  }
  if (typeof body.message !== 'string') {
    errors.push({ p: 'message', m: 'Falta el campo obligatorio "message"', d: 'Instrucción del editor' });
  } else {
    const trimmed = body.message.trim();
    if (trimmed.length < 2) errors.push({ p: 'message', m: 'Debe tener al menos 2 caracteres', d: 'Instrucción del editor' });
    else if (trimmed.length > 1200) errors.push({ p: 'message', m: 'Excede el máximo de 1200 caracteres', d: 'Instrucción del editor' });
  }
  if (body.mode !== undefined && (typeof body.mode !== 'string' || ALLOWED_MODES.indexOf(body.mode) === -1)) {
    errors.push({ p: 'mode', m: 'Modo editorial no permitido', d: 'Debe ser: chat, draft, improve o summarize' });
  }
  if (body.draft !== undefined && (typeof body.draft !== 'object' || body.draft === null || Array.isArray(body.draft))) {
    errors.push({ p: 'draft', m: 'El campo "draft" debe ser un objeto', d: 'Borrador actual' });
  }
  if (body.history !== undefined && (!Array.isArray(body.history) || body.history.length > 6)) {
    errors.push({ p: 'history', m: 'El historial debe ser un arreglo de máximo 6 mensajes', d: 'Historial reciente' });
  }

  if (errors.length === 0) return { valid: true, validationError: null };
  const details = {};
  for (let i = 0; i < errors.length; i++) {
    if (!(errors[i].p in details)) details[errors[i].p] = errors[i].m;
  }
  return {
    valid: false,
    validationError: 'Solicitud inválida (' + errors.length + '): ' + errors.map(e => e.p + ': ' + e.m).join('; '),
    details,
    requiredSchema: REQUIRED_SCHEMA
  };
})() }}

parameters.responseBody:
={{ (() => {
  // Devuelve error 400 estructurado cuando falla la validación de esquema
  const r = $('Validar Entrada Editorial').item.json.result;
  return {
    ok: false,
    error: 'validation_error',
    message: r.validationError,
    details: r.details,
    request_schema: r.requiredSchema,
  };
})() }}

parameters.text:
={{ (() => {
  // Construye el mensaje del editor delimitando los datos no confiables (OWASP LLM01)
  const body = $('Webhook (Cartelera IA S.I.G.A.)').item.json.body || {};
  const draft = body.draft || {};
  const history = Array.isArray(body.history) ? body.history.slice(-6) : [];
  const historyLines = history.length > 0
    ? history.map(h => (h.role === 'user' ? 'Editor: ' : 'Asistente: ') + String(h.content || '')).join('\n')
    : 'Sin mensajes previos.';

  return [
    'Modo solicitado: ' + (body.mode || 'chat'),
    '<borrador_actual>',
    'Título: ' + (draft.title || '(vacío)'),
    'Etiqueta corta: ' + (draft.shortNote || '(vacía)'),
    'Categoría: ' + (draft.category || 'evento'),
    'Audiencia: ' + (draft.audienceLabel || 'Toda la comunidad bellista'),
    'Lugar: ' + (draft.locationLabel || '(sin indicar)'),
    'Cuerpo:\n' + (draft.body || '(vacío)'),
    '</borrador_actual>',
    '<historial>',
    historyLines,
    '</historial>',
    '<solicitud_editor>',
    String(body.message || '').trim(),
    '</solicitud_editor>'
  ].join('\n');
})() }}

parameters.responseBody:
={{ (() => {
  // Normaliza y acota la salida estructurada antes de enviarla de vuelta a la Neon Function
  const raw = $('Redactor Editorial IA').item.json.output;
  const ALLOWED_CATS = ['urgente', 'evento', 'academico', 'mencion', 'cultura_deporte'];
  const stripHtml = (s, max) => String(s || '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<\/?[a-z][^>]*>/gi, '')
    .replace(/\r\n/g, '\n')
    .trim()
    .slice(0, max);

  let data = raw;
  if (typeof raw === 'string') {
    const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
    try { data = JSON.parse(cleaned); } catch (err) { return { ok: true, reply: stripHtml(cleaned, 1800), suggestion: null }; }
  }

  const reply = stripHtml(data?.reply || 'Preparé una propuesta lista para revisar en tu hoja.', 2000);
  const s = data?.hasSuggestion && data?.suggestion && typeof data.suggestion === 'object' ? data.suggestion : null;
  if (!s) return { ok: true, reply, suggestion: null };

  const out = {};
  const title = stripHtml(s.title, 80).replace(/\s+/g, ' ');
  const shortNote = stripHtml(s.shortNote, 32).replace(/\s+/g, ' ');
  const locationLabel = stripHtml(s.locationLabel, 120).replace(/\s+/g, ' ');
  const bodyText = stripHtml(s.body, 4000);
  const cat = String(s.category || '').trim().toLowerCase();

  if (title.length >= 4) out.title = title;
  if (shortNote.length >= 2) out.shortNote = shortNote;
  if (locationLabel.length >= 2) out.locationLabel = locationLabel;
  if (ALLOWED_CATS.indexOf(cat) !== -1) out.category = cat;
  if (bodyText.length >= 10) out.body = bodyText;

  return { ok: true, reply, suggestion: Object.keys(out).length > 0 ? out : null };
})() }}

={{ (() => {
  const msg = String($json.error?.message || $json.message || '').toLowerCase();
  if (msg.includes('timeout') || msg.includes('timed out')) {
    return { ok: false, error: 'upstream_timeout', message: 'El asistente editorial tardó demasiado en responder.' };
  }
  if (msg.includes('429') || msg.includes('rate limit') || msg.includes('too many')) {
    return { ok: false, error: 'service_unavailable', message: 'El servicio de redacción asistida está temporalmente saturado.' };
  }
  return { ok: false, error: 'upstream_error', message: 'No fue posible generar la propuesta editorial en este momento.' };
})() }}

options.responseCode:
={{ (() => {
  const msg = String($json.error?.message || $json.message || '').toLowerCase();
  if (msg.includes('timeout') || msg.includes('timed out')) return 504;
  if (msg.includes('429') || msg.includes('rate limit') || msg.includes('too many')) return 503;
  return 502;
})() }}
